function mkText(parent,name,text,{x=0,y=0,w,size=14,weight='Regular',color=C.ink,align='LEFT',lh}={}){
  const t = figma.createText();
  t.name = name;
  t.fontName = {family:'Inter',style:weight};
  t.characters = text;
  t.fontSize = size;
  if (lh) t.lineHeight = {unit:'PIXELS', value: lh}; else t.lineHeight = {unit:'PERCENT', value:130};
  t.fills = [{type:'SOLID', color: hex(color)}];
  t.textAlignHorizontal = align;
  if (w) { t.resize(w, t.height); t.textAutoResize='HEIGHT'; }
  parent.appendChild(t);
  t.x = x; t.y = y;
  return t;
}

function autoFrame(name,{mode='VERTICAL',gap=0,pl=0,pr=0,pt=0,pb=0,fillType='NONE',primaryAlign='MIN',counterAlign='MIN',sizing='AUTO'}={}){
  const f = figma.createFrame();
  f.name = name;
  f.layoutMode = mode;
  f.itemSpacing = gap;
  f.paddingLeft=pl; f.paddingRight=pr; f.paddingTop=pt; f.paddingBottom=pb;
  f.primaryAxisAlignItems = primaryAlign;
  f.counterAxisAlignItems = counterAlign;
  f.primaryAxisSizingMode = sizing;
  f.counterAxisSizingMode = sizing;
  f.fills = fillType==='NONE' ? [] : [{type:'SOLID', color: hex(fillType)}];
  f.clipsContent = false;
  return f;
}

async function iconInstance(iconId, size, color){
  const comp = await figma.getNodeByIdAsync(iconId);
  const inst = comp.createInstance();
  inst.resize(size,size);
  // recolor all vector descendants
  function recolor(n){
    if ('fills' in n && n.fills && n.fills.length) {
      const f = JSON.parse(JSON.stringify(n.fills));
      let changed=false;
      for (const fl of f) { if (fl.type==='SOLID'){ fl.color = hex(color); changed=true; } }
      if (changed) n.fills = f;
    }
    if (n.children) n.children.forEach(recolor);
  }
  recolor(inst);
  return inst;
}

