async function iconInstance(iconId,size,color){
  const comp = await figma.getNodeByIdAsync(iconId);
  const inst = comp.createInstance(); inst.resize(size,size);
  function recolor(n){ if('fills' in n && n.fills && n.fills.length){ const f=JSON.parse(JSON.stringify(n.fills)); let ch=false; for(const fl of f){ if(fl.type==='SOLID'){fl.color=hex(color); ch=true;} } if(ch) n.fills=f; } if(n.children) n.children.forEach(recolor); }
  recolor(inst); return inst;
}
async function imgInstance(imgId,w,h){
