function makeBubble(name, text, variant){
  const bubble = figma.createFrame();
  bubble.name = name;
  bubble.layoutMode='VERTICAL';
  bubble.primaryAxisSizingMode='AUTO';
  bubble.counterAxisSizingMode='AUTO';
  bubble.paddingTop=10; bubble.paddingBottom=10; bubble.paddingLeft=14; bubble.paddingRight=14;
  bubble.cornerRadius=16;
  if(variant==='sent'){
    bubble.fills=[{type:'SOLID', color:hex(BRAND)}];
    bubble.topLeftRadius=16; bubble.topRightRadius=16; bubble.bottomRightRadius=4; bubble.bottomLeftRadius=16;
  } else {
    bubble.fills=[{type:'SOLID', color:hex(SURF)}];
    bubble.topLeftRadius=16; bubble.topRightRadius=16; bubble.bottomRightRadius=16; bubble.bottomLeftRadius=4;
  }
  const txt = mkText('Text', text, 14, variant==='sent'?WHITE:INK, 'Regular', 220);
  txt.textAutoResize='WIDTH_AND_HEIGHT';
  txt.resize(Math.min(220, txt.width), txt.height);
  bubble.appendChild(txt);
  return bubble;
}
