function makeConvoRow(hasAvatar, unreadCount, name, msg, time, status){
  const row = figma.createFrame();
  row.name='C-ConversationRow';
  row.layoutMode='HORIZONTAL';
  row.primaryAxisSizingMode='FIXED';
  row.counterAxisSizingMode='AUTO';
  row.counterAxisAlignItems='CENTER';
  row.itemSpacing=12;
  row.resize(335, 64);
  row.fills=[];
  // avatar
  const av = figma.createEllipse();
  av.resize(48,48);
  av.fills=[{type:'SOLID', color:hex('#D8D3F8')}];
  const avWrap = figma.createFrame();
  avWrap.name='Avatar'; avWrap.resize(48,48); avWrap.fills=[];
  avWrap.appendChild(av); av.x=0; av.y=0;
  if(!hasAvatar){
    const initials = mkText('Initials', name.split(' ').map(w=>w[0]).join(''), 16, WHITE, 'Semi Bold');
    initials.textAlignHorizontal='CENTER';
    initials.resize(48, initials.height);
    initials.x=0; initials.y=16;
    av.fills=[{type:'SOLID', color:hex(BRAND)}];
    avWrap.appendChild(initials);
  }
  row.appendChild(avWrap);
  const body = figma.createFrame();
  body.name='Body'; body.layoutMode='VERTICAL'; body.primaryAxisSizingMode='AUTO'; body.counterAxisSizingMode='AUTO';
  body.itemSpacing=4; body.fills=[]; body.layoutSizingHorizontal='FILL';
  const nm = mkText('Name', name, 15, INK, 'Semi Bold', 180);
  const ms = mkText('Message', msg, 13, SUB, 'Regular', 180);
  body.appendChild(nm); body.appendChild(ms);
  row.appendChild(body);
  const right = figma.createFrame();
  right.name='Right'; right.layoutMode='VERTICAL'; right.primaryAxisSizingMode='AUTO'; right.counterAxisSizingMode='AUTO';
  right.counterAxisAlignItems='MAX'; right.itemSpacing=6; right.fills=[];
  const tm = mkText('Time', time, 12, SUB, 'Regular');
  right.appendChild(tm);
  if(unreadCount>0){
    const badge = figma.createFrame();
    badge.name='UnreadBadge'; badge.layoutMode='HORIZONTAL'; badge.primaryAxisAlignItems='CENTER'; badge.counterAxisAlignItems='CENTER';
    badge.primaryAxisSizingMode='AUTO'; badge.counterAxisSizingMode='AUTO';
    badge.paddingLeft=6; badge.paddingRight=6; badge.paddingTop=2; badge.paddingBottom=2;
    badge.cornerRadius=10; badge.fills=[{type:'SOLID', color:hex(BRAND)}];
    const bt = mkText('Count', String(unreadCount), 11, WHITE, 'Semi Bold');
    badge.appendChild(bt);
    right.appendChild(badge);
  } else if(status==='read'){
    const chk = mkText('Status','✓✓',12,BRAND,'Regular');
    right.appendChild(chk);
  } else if(status==='delivered'){
    const chk = mkText('Status','✓',12,SUB,'Regular');
    right.appendChild(chk);
  }
  row.appendChild(right);
  return row;
}
